public class Main {
    static class EstimationResult {
        double avgQps;
        double peakQps;
        double dailyStorageGB;
        double totalStorageGB;
        double peakBandwidthMBps;
    }

    static EstimationResult estimate(long dailyActiveUsers, double actionsPerUserPerDay,
                                      double avgPayloadBytes, double peakFactor, int retentionYears) {
        EstimationResult result = new EstimationResult();

        double totalActionsPerDay = dailyActiveUsers * actionsPerUserPerDay;
        result.avgQps = totalActionsPerDay / 86400.0;
        result.peakQps = result.avgQps * peakFactor;

        double dailyBytes = totalActionsPerDay * avgPayloadBytes;
        result.dailyStorageGB = dailyBytes / 1_000_000_000.0;
        result.totalStorageGB = result.dailyStorageGB * 365 * retentionYears;

        double peakBytesPerSecond = result.peakQps * avgPayloadBytes;
        result.peakBandwidthMBps = peakBytesPerSecond / 1_000_000.0;

        return result;
    }

    public static void main(String[] args) {
        // 100M DAU, 10 reads/user/day, 2KB per response, 3x peak factor, 5 year retention.
        EstimationResult r = estimate(100_000_000L, 10, 2048, 3.0, 5);

        System.out.printf("Average QPS: %.0f%n", r.avgQps);
        System.out.printf("Peak QPS: %.0f%n", r.peakQps);
        System.out.printf("Daily storage: %.2f GB%n", r.dailyStorageGB);
        System.out.printf("Total storage over retention: %.0f GB%n", r.totalStorageGB);
        System.out.printf("Peak bandwidth: %.2f MB/s%n", r.peakBandwidthMBps);
    }
}

