#include <iostream>
#include <cstdio>
using namespace std;

struct EstimationResult {
    double avgQps;
    double peakQps;
    double dailyStorageGB;
    double totalStorageGB;
    double peakBandwidthMBps;
};

EstimationResult estimate(long long dailyActiveUsers, double actionsPerUserPerDay,
                           double avgPayloadBytes, double peakFactor, int retentionYears) {
    EstimationResult result{};

    double totalActionsPerDay = dailyActiveUsers * actionsPerUserPerDay;
    result.avgQps = totalActionsPerDay / 86400.0;
    result.peakQps = result.avgQps * peakFactor;

    double dailyBytes = totalActionsPerDay * avgPayloadBytes;
    result.dailyStorageGB = dailyBytes / 1000000000.0;
    result.totalStorageGB = result.dailyStorageGB * 365 * retentionYears;

    double peakBytesPerSecond = result.peakQps * avgPayloadBytes;
    result.peakBandwidthMBps = peakBytesPerSecond / 1000000.0;

    return result;
}

int main() {
    // 100M DAU, 10 reads/user/day, 2KB per response, 3x peak factor, 5 year retention.
    EstimationResult r = estimate(100000000LL, 10, 2048, 3.0, 5);

    printf("Average QPS: %.0f\n", r.avgQps);
    printf("Peak QPS: %.0f\n", r.peakQps);
    printf("Daily storage: %.2f GB\n", r.dailyStorageGB);
    printf("Total storage over retention: %.0f GB\n", r.totalStorageGB);
    printf("Peak bandwidth: %.2f MB/s\n", r.peakBandwidthMBps);

    return 0;
}
